static
int32
_run_standard_decision(const StandardDecisionConfig *config_)
{
  StandardDecisionState state;
  int32 audio_result;
  int32 buttons;
  int32 choice;
  int32 cleanup_result;
  int32 help_visible;
  int32 result;
  int32 running;
  int32 selection_changed;
  int32 voiced_choice;

  choice = 1;
  result = _init_standard_decision(config_, &state);
  if(result != 0)
    {
      goto cleanup;
    }

  help_visible      = 0;
  running           = 1;
  voiced_choice     = 0;
  selection_changed = 0;
  _set_standard_decision_flags(config_, choice);

  while(running)
    {
      _draw_standard_decision(config_, &state, help_visible);

      selection_changed = 0;
      result            = WaitVBL(state.vbl_io_req, 1);
      if(result < 0)
        {
          break;
        }
      audio_result = DecisionAudioService(&state.audio);
      if(audio_result < 0)
        {
          result = audio_result;
          break;
        }

      buttons      = GetJoypad();
      help_visible = ((controlPadPrevious.cped_ButtonBits & CONTROL_LEFT_SHIFT) != 0);
      if(controlPadLastError < 0)
        {
          result = controlPadLastError;
          break;
        }
      if(buttons == (int32)CONTROL_RIGHT_SHIFT)
        {
          result  = config_->exit_result;
          running = 0;
        }
      else if(buttons == (int32)CONTROL_DOWN)
        {
          choice++;
          if(choice > config_->choice_count)
            {
              choice = 1;
            }
          _set_standard_decision_flags(config_, choice);
          selection_changed = 1;
        }
      else if(!help_visible && buttons == (int32)CONTROL_A)
        {
          running = 0;
        }
      else if(!help_visible && buttons == (int32)CONTROL_UP)
        {
          choice--;
          if(choice < 1)
            {
              choice = config_->choice_count;
            }
          _set_standard_decision_flags(config_, choice);
          selection_changed = 1;
        }

      if(selection_changed && running)
        {
          _draw_standard_decision(config_, &state, help_visible);
        }

      if(running && choice != voiced_choice)
        {
          audio_result = DecisionAudioStart(
            &state.audio,
            (uint8 *)config_->sound_paths[choice - 1],
            PDWT_SOUNDFILE_BUFFER_SIZE,
            PDWT_SOUNDFILE_AMPLITUDE);
          if(audio_result < 0)
            {
              result = audio_result;
              break;
            }
          voiced_choice = choice;
        }
    }

cleanup:
  _restore_next_screen(state.vram_io_req);
  cleanup_result = _cleanup_standard_decision(config_, &state);
  if(cleanup_result < 0 && result >= 0)
    {
      result = cleanup_result;
    }
  if(result != 0)
    {
      return result;
    }
  return choice;
}


static
int32
_init_standard_decision(const StandardDecisionConfig *config_,
                        StandardDecisionState        *state_)
{
  int32 i;
  int32 result;

  memset(state_, 0, sizeof(*state_));
  DecisionAudioInit(&state_->audio);

  result = InitEventUtility(1, 0, 1);
  if(result != 0)
    {
      return result < 0 ? result : -1;
    }
  state_->event_open = 1;

  state_->vram_io_req = GetVRAMIOReq();
  if(state_->vram_io_req < 0)
    {
      return state_->vram_io_req;
    }
  state_->vbl_io_req = GetVBLIOReq();
  if(state_->vbl_io_req < 0)
    {
      return state_->vbl_io_req;
    }

  for(i = 0; i < config_->choice_count; i++)
    {
      state_->normal[i] = LoadCel((char *)config_->normal_paths[i], PDWT_MEMTYPE_CEL);
      if(state_->normal[i] == NULL)
        {
          return -1;
        }
      state_->selected[i] = LoadCel((char *)config_->selected_paths[i], PDWT_MEMTYPE_CEL);
      if(state_->selected[i] == NULL)
        {
          return -1;
        }

      _setup_decision_cel(state_->normal[i], 80, config_->cel_height, 0, 0);
      _setup_decision_cel(
        state_->selected[i],
        80,
        config_->cel_height,
        DECISION_SELECTED_X,
        0);
    }

  state_->help = LoadCel((char *)config_->help_path, PDWT_MEMTYPE_CEL);
  if(state_->help == NULL)
    {
      return -1;
    }

  sprintf((char *)state_->score_text, "SCORES:%d", point);
  return 0;
}


static
void
_set_standard_decision_flags(const StandardDecisionConfig *config_,
                             int32                         choice_)
{
  if(config_->choice_count == 3)
    {
      _set_dec07_render_flags(choice_);
    }
  else
    {
      _set_dec12_render_flags(choice_);
    }
}


static
void
_draw_standard_decision(const StandardDecisionConfig *config_,
                        StandardDecisionState        *state_,
                        int32                         help_visible_)
{
  if(config_->choice_count == 3)
    {
      _draw_dec07_scene(
        state_->vram_io_req,
        &state_->gcon,
        state_->score_text,
        state_->normal[0],
        state_->normal[1],
        state_->normal[2],
        state_->selected[0],
        state_->selected[1],
        state_->selected[2],
        state_->help,
        help_visible_);
    }
  else
    {
      _draw_dec12_scene(
        state_->vram_io_req,
        &state_->gcon,
        state_->score_text,
        state_->normal[0],
        state_->normal[1],
        state_->selected[0],
        state_->selected[1],
        state_->help,
        help_visible_);
    }
}


static
int32
_cleanup_standard_decision(const StandardDecisionConfig *config_,
                           StandardDecisionState        *state_)
{
  int32 cleanup_result;
  int32 i;
  int32 result;

  result = DecisionAudioStop(&state_->audio);
  if(state_->event_open)
    {
      cleanup_result = KillEventUtility();
      if(cleanup_result < 0 && result >= 0)
        {
          result = cleanup_result;
        }
    }

  for(i = 0; i < config_->choice_count; i++)
    {
      if(state_->normal[i] != NULL)
        {
          UnloadCel(state_->normal[i]);
        }
      if(state_->selected[i] != NULL)
        {
          UnloadCel(state_->selected[i]);
        }
    }
  if(state_->help != NULL)
    {
      UnloadCel(state_->help);
    }

  if(state_->vbl_io_req > 0)
    {
      cleanup_result = DeleteItem(state_->vbl_io_req);
      if(cleanup_result < 0 && result >= 0)
        {
          result = cleanup_result;
        }
    }
  if(state_->vram_io_req > 0)
    {
      cleanup_result = DeleteItem(state_->vram_io_req);
      if(cleanup_result < 0 && result >= 0)
        {
          result = cleanup_result;
        }
    }

  return result;
}


static
CCB *
_load_scene_cel(char         *pathFormat_,
                SceneCelInfo *info_,
                uint8        *path_)
{
  CCB *cel;

  sprintf((char *)path_, pathFormat_, info_->CelFileName);
  cel = LoadCel((char *)path_, PDWT_MEMTYPE_CEL);
  return cel;
}


static
void
_prepare_scene_cel(CCB *cel_)
{
  cel_->ccb_Flags |= 0x40000000;
  cel_->ccb_XPos = ((320 - cel_->ccb_Width) / 2) << 16;
  cel_->ccb_YPos = 0;
}


static
uint32
_scene_table_fields(const SceneCelInfo *table_,
                    int32               count_)
{
  uint32 fields;
  int32 frame;

  fields = 0;
  for(frame = 0; frame < count_; frame++)
    {
      fields += (uint32)table_[frame].CelLength;
    }
  return fields;
}


static
int32
_wait_for_scene_fields(Item  vblIOReq_,
                       int32 fields_)
{
  int32 result;

  result = PDWTSceneControlWaitFields(vblIOReq_, fields_);
  if(result == PDWT_INPUT_STOP)
    {
      return 3;
    }
  return result;
}


static
int32
_wait_for_scene_clock(PDWTSceneClock *clock_,
                      Item            vblIOReq_,
                      int32           fields_)
{
  int32 result;

  result = PDWTSceneControlWaitClock(clock_, vblIOReq_, fields_);
  if(result == PDWT_INPUT_STOP)
    {
      return 3;
    }
  return result;
}


static
int32
_wait_for_scene_audio(DecisionAudio *audio_,
                      Item           vblIOReq_)
{
  return PDWTSceneControlWaitAudio(audio_, vblIOReq_);
}


static
int32
_wait_for_uncalibrated_scene_audio(const PDWTSceneClock *clock_,
                                   DecisionAudio        *audio_,
                                   Item                  vblIOReq_)
{
  if(PDWTSceneClockIsCalibrated(clock_))
    {
      return 0;
    }
  return _wait_for_scene_audio(audio_, vblIOReq_);
}


static
int32
_wait_for_calibrated_scene_end(PDWTSceneClock *clock_,
                               Item            vblIOReq_)
{
  int32 result;

  if(!PDWTSceneClockIsCalibrated(clock_))
    {
      return 0;
    }
  result = PDWTSceneControlWaitClockEnd(clock_, vblIOReq_);
  if(result == PDWT_INPUT_STOP)
    {
      return 3;
    }
  return result;
}


static
int32
_stop_scene_audio(DecisionAudio *audio_,
                  int32          result_)
{
  int32 stopResult;

  stopResult = DecisionAudioStop(audio_);
  if(stopResult < 0 && result_ >= 0)
    {
      return stopResult;
    }
  return result_;
}


static
int32
_finish_scene_result(int32 result_)
{
  if(result_ == PDWT_SCENE_CONTROL_SKIP)
    {
      return 1;
    }
  if(result_ != 0)
    {
      return result_ == 1 ? -1 : result_;
    }
  return 1;
}


static
int32
_draw_scene_cel(Item  vramIOReq_,
                Item  vblIOReq_,
                CCB  *cel_,
                int32 fields_)
{
  int32 result;

  if(vramIOReq_ <= 0 || vblIOReq_ <= 0 || cel_ == NULL)
    {
      return -1;
    }

  gScreenContext.sc_curScreen = 1 - gScreenContext.sc_curScreen;
  result = SetVRAMPages(
    vramIOReq_,
    gScreenContext.sc_Bitmaps[gScreenContext.sc_curScreen]->bm_Buffer,
    0,
    gScreenContext.sc_nFrameBufferPages,
    -1);
  if(result < 0)
    {
      return result;
    }
  result = DrawCels(gScreenContext.sc_BitmapItems[gScreenContext.sc_curScreen], cel_);
  if(result < 0)
    {
      return result;
    }
  result = DisplayScreen(gScreenContext.sc_Screens[gScreenContext.sc_curScreen], 0);
  if(result < 0)
    {
      return result;
    }
  PDWTSceneControlPresent(gScreenContext.sc_curScreen);
  return _wait_for_scene_fields(vblIOReq_, fields_);
}


static
int32
_draw_scene_table_frame(char           *pathFormat_,
                        SceneCelInfo   *info_,
                        Item            vramIOReq_,
                        Item            vblIOReq_,
                        uint8          *path_,
                        PDWTSceneClock *clock_)
{
  CCB  *cel;
  int32 result;

  if(vramIOReq_ <= 0 || vblIOReq_ <= 0)
    {
      return -1;
    }

  cel = _load_scene_cel(pathFormat_, info_, path_);
  if(cel == NULL)
    {
      return -1;
    }
  _prepare_scene_cel(cel);
  result = _draw_scene_cel(vramIOReq_, vblIOReq_, cel, 0);
  UnloadCel(cel);
  if(result == 0)
    {
      result = _wait_for_scene_clock(clock_, vblIOReq_, info_->CelLength);
    }
  return result;
}


static
void
_flip_screen(void)
{
  gScreenContext.sc_curScreen = 1 - gScreenContext.sc_curScreen;
}


static
void
_clear_current_screen(Item vramIOReq_)
{
  Bitmap *bitmap;

  if(vramIOReq_ <= 0)
    {
      return;
    }

  bitmap = gScreenContext.sc_Bitmaps[gScreenContext.sc_curScreen];
  if(bitmap == NULL)
    {
      return;
    }

  SetVRAMPages(vramIOReq_, bitmap->bm_Buffer, 0, gScreenContext.sc_nFrameBufferPages, -1);
}


static
void
_show_current_screen(void)
{
  DisplayScreen(gScreenContext.sc_Screens[gScreenContext.sc_curScreen], 0);
  PDWTSceneControlPresent(gScreenContext.sc_curScreen);
}


static
void
_restore_next_screen(Item vramIOReq_)
{
  Bitmap *bitmap;

  if(vramIOReq_ <= 0)
    {
      return;
    }

  gScreenContext.sc_curScreen = 1 - gScreenContext.sc_curScreen;
  bitmap                      = gScreenContext.sc_Bitmaps[gScreenContext.sc_curScreen];
  if(bitmap != NULL)
    {
      SetVRAMPages(vramIOReq_, bitmap->bm_Buffer, 0, gScreenContext.sc_nFrameBufferPages, -1);
    }
  DisplayScreen(gScreenContext.sc_Screens[gScreenContext.sc_curScreen], 0);
  PDWTSceneControlPresent(gScreenContext.sc_curScreen);
}


static
void
_draw_transition_frame(Item   vramIOReq_,
                       CCB   *cel_,
                       Point *quad_)
{
  if(vramIOReq_ <= 0 || cel_ == NULL || quad_ == NULL)
    {
      return;
    }

  _flip_screen();
  MapCel(cel_, quad_);
  _clear_current_screen(vramIOReq_);
  DrawCels(gScreenContext.sc_BitmapItems[gScreenContext.sc_curScreen], cel_);
  _show_current_screen();
}


static
void
_init_quad(Point *quad_,
           Coord  x0_,
           Coord  y0_,
           Coord  x1_,
           Coord  y1_,
           Coord  x2_,
           Coord  y2_,
           Coord  x3_,
           Coord  y3_)
{
  quad_[0].pt_X = x0_;
  quad_[0].pt_Y = y0_;
  quad_[1].pt_X = x1_;
  quad_[1].pt_Y = y1_;
  quad_[2].pt_X = x2_;
  quad_[2].pt_Y = y2_;
  quad_[3].pt_X = x3_;
  quad_[3].pt_Y = y3_;
}


int32
FUNeffectout(CCB *cel_)
{
  Item vramIOReq;
  Point quad[4];
  int32 result;

  result    = 0;
  vramIOReq = GetVRAMIOReq();
  if(vramIOReq < 0)
    {
      return vramIOReq;
    }

  _flip_screen();
  _clear_current_screen(vramIOReq);
  _show_current_screen();
  result = PDWTSceneControlPoll();
  if(result != PDWT_SCENE_CONTROL_CONTINUE)
    {
      goto cleanup;
    }

  _init_quad(quad, 120, 120, 200, 120, 200, 120, 120, 120);
  while(quad[0].pt_X > 0)
    {
      quad[0].pt_X--;
      quad[0].pt_Y--;
      quad[1].pt_X++;
      quad[1].pt_Y--;
      quad[2].pt_X++;
      quad[2].pt_Y++;
      quad[3].pt_X--;
      quad[3].pt_Y++;
      _draw_transition_frame(vramIOReq, cel_, quad);
      result = PDWTSceneControlPoll();
      if(result != PDWT_SCENE_CONTROL_CONTINUE)
        {
          goto cleanup;
        }
    }

cleanup:
  if(vramIOReq > 0)
    {
      DeleteItem(vramIOReq);
    }
  return result;
}


