int32
shakeeffect(CCB *cel_)
{
  Item vramIOReq;
  Item vblIOReq;
  Point quad[4];
  int32 outer;
  int32 inner;
  int32 result;

  outer     = 0;
  inner     = 0;
  result    = 0;
  vramIOReq = GetVRAMIOReq();
  vblIOReq  = GetVBLIOReq();
  if(vramIOReq < 0 || vblIOReq < 0)
    {
      result = -1;
      goto cleanup;
    }

  _flip_screen();
  _clear_current_screen(vramIOReq);
  result = _wait_for_scene_fields(vblIOReq, 16);
  if(result != 0)
    {
      goto cleanup;
    }

  _init_quad(quad, 0, 0, 320, 0, 320, 240, 0, 240);
  while(outer < 5)
    {
      while(inner < 8)
        {
          quad[0].pt_X -= 35;
          quad[1].pt_X += 35;
          quad[2].pt_X += 35;
          quad[3].pt_X -= 35;
          quad[2].pt_Y += 70;
          quad[3].pt_Y += 70;
          _draw_transition_frame(vramIOReq, cel_, quad);
          result = _wait_for_scene_fields(vblIOReq, 1);
          if(result != 0)
            {
              goto cleanup;
            }
          inner++;
        }
      while(inner < 16)
        {
          quad[0].pt_X += 35;
          quad[1].pt_X -= 35;
          quad[2].pt_X -= 35;
          quad[3].pt_X += 35;
          quad[2].pt_Y -= 70;
          quad[3].pt_Y -= 70;
          _draw_transition_frame(vramIOReq, cel_, quad);
          result = _wait_for_scene_fields(vblIOReq, 1);
          if(result != 0)
            {
              goto cleanup;
            }
          inner++;
        }
      inner = 0;
      outer++;
    }

  _flip_screen();
  _clear_current_screen(vramIOReq);
  DrawCels(gScreenContext.sc_BitmapItems[gScreenContext.sc_curScreen], cel_);
  _show_current_screen();
  result = _wait_for_scene_fields(vblIOReq, 11);

cleanup:
  if(vramIOReq > 0)
    {
      DeleteItem(vramIOReq);
    }
  if(vblIOReq > 0)
    {
      DeleteItem(vblIOReq);
    }
  return result;
}


int32
PlaySoundFile(SoundFilePlayer *sfp_,
              uint8           *FileName_)
{
  int32 cleanupResult;
  int32 err;
  int32 signalIn;
  int32 signalNeeded;
  int32 loaded;
  int32 started;

  err          = 0;
  signalIn     = 0;
  signalNeeded = 0;
  loaded       = 0;
  started      = 0;

  if(sfp_ == NULL)
    {
      return -1;
    }

  err = LoadSoundFile(sfp_, (char *)FileName_);
  if(err < 0)
    {
      return err;
    }
  loaded = 1;

  err = StartSoundFile(sfp_, 0x7fff);
  if(err < 0)
    {
      goto cleanup;
    }
  started = 1;

  do
    {
      err = ServiceSoundFile(sfp_, signalIn, &signalNeeded);
      if(err < 0)
        {
          goto cleanup;
        }
      if(signalNeeded != 0)
        {
          signalIn = WaitSignal((uint32)signalNeeded);
        }
    } while(signalNeeded != 0);

cleanup:
  if(started)
    {
      cleanupResult = StopSoundFile(sfp_);
      if(cleanupResult < 0)
        {
          return err < 0 ? err : cleanupResult;
        }
    }
  if(loaded)
    {
      cleanupResult = UnloadSoundFile(sfp_);
      if(cleanupResult < 0)
        {
          return err < 0 ? err : cleanupResult;
        }
    }

  return err < 0 ? err : 0;
}


int32
DEC00(void)
{
  DecisionAudio decisionAudio;
  Item vramIOReq;
  Item vblIOReq;
  GrafCon gcon;
  uint8 scoreText[28];
  const uint8 *sound_name;
  CCB          *eccb1;
  CCB          *eccb1w;
  CCB          *eccb2;
  CCB          *eccb2w;
  CCB          *controlhelp;
  int32 choice;
  int32 voicedChoice;
  int32 running;
  int32 canPlaySound;
  int32 eventOpen;
  int32 audioEnabled;
  int32 renderReady;
  int32 cel1Loaded;
  int32 cel2Loaded;
  int32 cel3Loaded;
  int32 cel4Loaded;
  int32 cel5Loaded;
  int32 helpVisible;
  int32 ticks;
  int32 buttons;
  int32 result;
  int32 eventErr;
  int32 audioResult;

  DecisionAudioInit(&decisionAudio);
  vramIOReq        = 0;
  vblIOReq         = 0;
  eccb1            = 0;
  eccb1w           = 0;
  eccb2            = 0;
  eccb2w           = 0;
  controlhelp      = 0;
  choice           = 1;
  voicedChoice     = 0;
  running          = 1;
  canPlaySound     = 1;
  eventOpen        = 0;
  audioEnabled     = DEC00_ENABLE_SOUND;
  renderReady      = 1;
  cel1Loaded       = 1;
  cel2Loaded       = 1;
  cel3Loaded       = 1;
  cel4Loaded       = 1;
  cel5Loaded       = 1;
  helpVisible      = 0;
  ticks            = 0;
  result           = 1;

  eventErr = InitEventUtility(1, 0, 1);
  if(eventErr != 0)
    {
      canPlaySound = 0;
      eventOpen    = 0;
    }
  else
    {
      eventOpen = 1;
    }

  vramIOReq = GetVRAMIOReq();
  vblIOReq = GetVBLIOReq();
  if(vramIOReq < 0 || vblIOReq < 0)
    {
      result      = -1;
      renderReady = 0;
      running     = 0;
    }

  eccb1 = LoadCel(DEC00_PIC1, PDWT_MEMTYPE_CEL);
  if(eccb1 == 0)
    {
      cel1Loaded = 0;
    }
  eccb1w = LoadCel(DEC00_PIC2, PDWT_MEMTYPE_CEL);
  if(eccb1w == 0)
    {
      cel2Loaded = 0;
    }
  eccb2 = LoadCel(DEC00_PIC3, PDWT_MEMTYPE_CEL);
  if(eccb2 == 0)
    {
      cel3Loaded = 0;
    }
  eccb2w = LoadCel(DEC00_PIC4, PDWT_MEMTYPE_CEL);
  if(eccb2w == 0)
    {
      cel4Loaded = 0;
    }
  controlhelp = LoadCel(DEC00_HELP, PDWT_MEMTYPE_CEL);
  if(controlhelp == 0)
    {
      cel5Loaded = 0;
    }

  renderReady = (Cel4 != 0 && Cel5 != 0);
  if(!cel1Loaded || !cel2Loaded || !cel3Loaded || !cel4Loaded || !cel5Loaded || !renderReady ||
     !canPlaySound)
    {
      result  = -1;
      running = 0;
    }

  if(running)
    {
      _set_dec00_cel_pos(eccb1);
      _set_dec00_cel_pos(eccb1w);
      _set_dec00_cel_pos(eccb2);
      _set_dec00_cel_pos(eccb2w);
      eccb1->ccb_XPos  = 0;
      eccb1->ccb_YPos  = 0;
      eccb2->ccb_XPos  = 0;
      eccb2->ccb_YPos  = 0;
      eccb1w->ccb_XPos = 0x500000;
      eccb1w->ccb_YPos = 0;
      eccb2w->ccb_XPos = 0x500000;
      eccb2w->ccb_YPos = 0;

      _set_dec00_render_flags(choice);
      sprintf((char *)scoreText, "SCORES:%d", point);

      while(running && ticks < DEC00_TIMEOUT)
        {
          WaitVBL(vblIOReq, 1);
          audioResult = DecisionAudioService(&decisionAudio);
          buttons     = GetJoypad();

          if(audioResult < 0)
            {
              canPlaySound = 0;
              result       = -1;
              running      = 0;
            }
          else if(controlPadLastError < 0)
            {
              result  = -1;
              running = 0;
            }
          else if(buttons == (int32)CONTROL_A)
            {
              result  = choice;
              running = 0;
            }
          else if(buttons == (int32)CONTROL_DOWN)
            {
              choice++;
              if(choice > 2)
                {
                  choice = 1;
                }
              _set_dec00_render_flags(choice);
              ticks            = 0;
            }
          else if(buttons == (int32)CONTROL_LEFT_SHIFT)
            {
              helpVisible = 1;
              ticks       = 0;
            }
          else if(buttons == (int32)CONTROL_UP)
            {
              choice--;
              if(choice < 1)
                {
                  choice = 2;
                }
              _set_dec00_render_flags(choice);
              ticks            = 0;
            }

          _draw_dec00_scene(vramIOReq, &gcon, scoreText, eccb1, eccb1w, eccb2, eccb2w, controlhelp,
                            helpVisible);
          if(helpVisible)
            {
              helpVisible = 0;
              continue;
            }

          if(running && audioEnabled && canPlaySound && choice != voicedChoice)
            {
              if(choice == 1)
                {
                  sound_name = (const uint8 *)DEC00_SOUND1;
                }
              else
                {
                  sound_name = (const uint8 *)DEC00_SOUND2;
                }

              audioResult =
                DecisionAudioStart(&decisionAudio, (uint8 *)sound_name, PDWT_SOUNDFILE_BUFFER_SIZE,
                                   PDWT_SOUNDFILE_AMPLITUDE);
              if(audioResult < 0)
                {
                  canPlaySound = 0;
                  result       = -1;
                  running      = 0;
                }
              else
                {
                  voicedChoice = choice;
                }
            }

          ticks++;
        }
    }

  _restore_next_screen(vramIOReq);

  audioResult = DecisionAudioStop(&decisionAudio);
  if(audioResult < 0 && result >= 0)
    {
      result = audioResult;
    }

  if(eventOpen)
    {
      KillEventUtility();
    }
  if(cel1Loaded)
    {
      UnloadCel(eccb1);
    }
  if(cel3Loaded)
    {
      UnloadCel(eccb2);
    }
  if(cel2Loaded)
    {
      UnloadCel(eccb1w);
    }
  if(cel4Loaded)
    {
      UnloadCel(eccb2w);
    }
  if(cel5Loaded)
    {
      UnloadCel(controlhelp);
    }
  if(vramIOReq > 0)
    {
      DeleteItem(vramIOReq);
    }
  if(vblIOReq > 0)
    {
      DeleteItem(vblIOReq);
    }

  if(running && ticks >= DEC00_TIMEOUT && result >= 0)
    {
      result = 3;
    }
  return result;
}


