int32
FunSC04(void)
{
  DecisionAudio sceneAudio;
  PDWTSceneControl sceneControl;
  PDWTSceneClock sceneClock;
  SceneCelInfo *table;
  char         *pathFormat;
  char         *soundFileName;
  Item vblIOReq;
  Item vramIOReq;
  CCB          *cel;
  CCB          *ratingCel;
  uint8 path[42];
  int32 eventOpen;
  int32 result;
  int32 frame;
  int32 i;

  table         = secretpass ? FILE_SC44 : FILE_SC04;
  pathFormat    = secretpass ? SC04A_PATH_FORMAT : SC04_PATH_FORMAT;
  soundFileName = secretpass ? SC04A_SOUND_FILE : SC04_SOUND_FILE;
  DecisionAudioInit(&sceneAudio);
  PDWTSceneControlInit(&sceneControl);
  memset(&sceneClock, 0, sizeof(sceneClock));
  frame         = 0;
  result        = 0;
  ratingCel     = 0;
  eventOpen     = 0;
  vblIOReq      = 0;
  vramIOReq     = 0;

  if(!secretpass)
    {
      ratingCel = LoadCel(SC04_RATING_CEL, PDWT_MEMTYPE_CEL);
      if(ratingCel == 0)
        {
          result = 1;
          goto cleanup;
        }
      ratingCel->ccb_XPos = 100 << 16;
      ratingCel->ccb_YPos = 90 << 16;
      ratingCel->ccb_Flags |= 0x40000000;
    }

  vblIOReq  = GetVBLIOReq();
  vramIOReq = GetVRAMIOReq();
  if(vblIOReq < 0 || vramIOReq < 0)
    {
      result = 1;
      goto cleanup;
    }

  if(InitEventUtility(1, 0, 1) != 0)
    {
      eventOpen = 0;
      result    = 1;
      goto cleanup;
    }
  eventOpen = 1;
  result = PDWTSceneControlBegin(
    &sceneControl, &gScreenContext, vramIOReq, vblIOReq, &sceneAudio, &sceneClock);
  if(result != PDWT_SCENE_CONTROL_CONTINUE)
    {
      goto cleanup;
    }

  cel = _load_scene_cel(pathFormat, &table[0], path);
  if(cel == NULL)
    {
      result = 1;
      goto cleanup;
    }
  cel->ccb_Flags |= 0x40000000;
  result = FUNeffectout(cel);
  UnloadCel(cel);
  if(result != PDWT_SCENE_CONTROL_CONTINUE)
    {
      goto cleanup;
    }

  result = DecisionAudioStartWithBuffers(
    &sceneAudio,
    (uint8 *)soundFileName,
    PDWT_STORY_BUFFER_COUNT,
    PDWT_STORY_BUFFER_SIZE,
    PDWT_SOUNDFILE_AMPLITUDE);
  if(result < 0)
    {
      goto cleanup;
    }
  if(ratingCel != 0)
    {
      PDWTSceneClockStart(
        &sceneClock,
        (uint8 *)"sc04",
        _scene_table_fields(table, SC04_RATING_START_FRAME) +
        ((23 - SC04_RATING_START_FRAME) * SC04_RATING_FIELDS));
    }
  else
    {
      PDWTSceneClockStart(&sceneClock, (uint8 *)"sc04", _scene_table_fields(table, 23));
    }

  while(frame < 5)
    {
      result = _draw_scene_table_frame(pathFormat, &table[frame], vramIOReq, vblIOReq, path,
                                       &sceneClock);
      if(result != 0)
        {
          goto cleanup;
        }
      frame++;
    }

  while(frame < 23)
    {
      cel = _load_scene_cel(pathFormat, &table[frame], path);
      if(cel == NULL)
        {
          result = 1;
          goto cleanup;
        }
      _prepare_scene_cel(cel);

      if(ratingCel != 0)
        {
          for(i = 0; i < SC04_RATING_FIELDS; i++)
            {
              result = _draw_scene_cel(vramIOReq, vblIOReq, cel, 1);
              if(result != 0)
                {
                  UnloadCel(cel);
                  goto cleanup;
                }
              if((i % 10) != 0)
                {
                  result = DrawCels(gScreenContext.sc_BitmapItems[gScreenContext.sc_curScreen],
                                    ratingCel);
                  if(result < 0)
                    {
                      UnloadCel(cel);
                      goto cleanup;
                    }
                }
            }
          result = _wait_for_scene_clock(&sceneClock, vblIOReq, SC04_RATING_FIELDS);
          if(result != 0)
            {
              UnloadCel(cel);
              goto cleanup;
            }
        }
      else
        {
          result = _draw_scene_cel(vramIOReq, vblIOReq, cel, 0);
          if(result == 0)
            {
              result = _wait_for_scene_clock(&sceneClock, vblIOReq, table[frame].CelLength);
            }
          if(result != 0)
            {
              UnloadCel(cel);
              goto cleanup;
            }
        }

      UnloadCel(cel);
      frame++;
    }

  result = _wait_for_uncalibrated_scene_audio(&sceneClock, &sceneAudio, vblIOReq);
  if(result != 0)
    {
      goto cleanup;
    }

  if(result == 0)
    {
      cel = _load_scene_cel(pathFormat, &table[22], path);
      if(cel == NULL)
        {
          result = 1;
          goto cleanup;
        }
      cel->ccb_Flags |= 0x40000000;
      result = FUNeffectinh(cel);
      UnloadCel(cel);
      if(result != 0)
        {
          goto cleanup;
        }
    }

  result = _wait_for_calibrated_scene_end(&sceneClock, vblIOReq);
  if(result != 0)
    {
      goto cleanup;
    }

cleanup:
  PDWTSceneControlEnd(&sceneControl);
  result = _stop_scene_audio(&sceneAudio, result);
  if(ratingCel != 0)
    {
      UnloadCel(ratingCel);
    }
  _restore_next_screen(vramIOReq);
  if(vblIOReq > 0)
    {
      DeleteItem(vblIOReq);
    }
  if(vramIOReq > 0)
    {
      DeleteItem(vramIOReq);
    }
  if(eventOpen)
    {
      int32 cleanup_result;

      cleanup_result = KillEventUtility();
      if((cleanup_result < 0) && (result >= 0))
        {
          result = cleanup_result;
        }
    }

  return _finish_scene_result(result);
}


